    if (arg > CDROM_DISC_TRAY_STATUS)
        return -EINVAL;

    info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    ret = cdrom_read_mechanism_status(cdi, info);
