int cdrom_ioctl_check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;
    struct cdrom_changer_info *info = NULL;

    if (!cdi->ops->check_media_change)
        return -ENOSYS;

    if (arg >= CDROM_MAX_DISC_COUNT)
        return -EINVAL;

    info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    ret = cdi->ops->check_media_change(cdi, arg, info);
    if (ret < 0)
        goto out;

    ret = (info->disc_status == CDROM_DISC_CHANGED) ? 0 : -ENOMSG;

out:
    kfree(info);
    return ret;
}

int cdrom_ioctl_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;

    if (!cdi->media_change)
        return -ENOSYS;

    if (arg >= CDROM_MAX_DISC)
        return -EINVAL;

    void *changer_info = kmalloc(sizeof(struct cdrom_changer_info), GFP_KERNEL);
    if (!changer_info)
        return -ENOMEM;

    ret = cdi->media_change(cdi, arg, changer_info);
    if (ret < 0)
        goto out;

    ret = 0;

out:
    kfree(changer_info);
    return ret;
}

int cdrom_ioctl_check_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    int ret = -ENOSYS;

    if (!cdi || !cdi->ops || !cdi->ops->check_media_change)
        return -EINVAL;

    if (arg > CDROM_DISC_OTHER)
        return -EINVAL;

    if (arg == CDROM_DISC_OTHER && !cdi->can_select_disc)
        return -ENOSYS;

    ret = cdi->ops->check_media_change(cdi, arg);
    if (ret < 0)
        return ret;

    return 0;
}

#include <linux/cdrom.h>
#include <linux/errno.h>
#include <linux/slab.h>

int handle_ioctl_media_change(struct cdrom_device_info *cdi, unsigned long arg)
{
    if (!(cdi->mask & CDROM_MEDIA_CHANGED))
        return -ENOSYS;

    if (arg > CDROM_DISC_TRAY)
        return -EINVAL;

    struct cdrom_changer_info *info = kmalloc(sizeof(*info), GFP_KERNEL);
    if (!info)
        return -ENOMEM;

    int ret = cdrom_read_mech_status(cdi, info);
    if (ret) {
        kfree(info);
        return ret;
    }

    int result = -ENOSYS;
    if (arg == CDROM_DISC_TRAY) {
        result = info->tray_status;
    } else if (arg == CDROM_DISC_PRESENT) {
        result = info->disc_present;
    } else if (arg == CDROM_DISC_STATUS) {
        result = info->disc_status;
    }

    kfree(info);
    return result;
}
